  first [ match goal with |- context [Z.land ((Z.shiftr (bv_signed (Z_to_bv 64 ?x)) 63) mod 18446744073709551616) (?x mod 18446744073709551616)] =>
            rewrite (min_idiom_s x) by lia end
        | match goal with |- context [Z.land ((bv_signed (Z_to_bv 64 ?x) / 9223372036854775808) mod 18446744073709551616) (?x mod 18446744073709551616)] =>
